import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2023Q3 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2023Q3 Ceph社区季度进展报告","date":"2023-09-01T00:00:00.000Z","updated":"2023-09-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/2023Q3_Ceph社区季度总结.md","filePath":"posts/2023/2023Q3_Ceph社区季度总结.md","lastUpdated":1780460162000}'),i={name:"posts/2023/2023Q3_Ceph社区季度总结.md"};function l(h,e,s,_,n,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>我将基于这21篇会议总结材料，生成一份完整的Ceph社区2023Q3季度进展报告。</p><hr><h1 id="ceph-社区-2023q3-季度进展报告" tabindex="-1">Ceph 社区 2023Q3 季度进展报告 <a class="header-anchor" href="#ceph-社区-2023q3-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2023Q3 季度进展报告&quot;">​</a></h1><p><strong>报告周期：</strong> 2023年7月 - 2023年9月<br><strong>数据来源：</strong> 21篇社区会议与技术分享总结</p><hr><h2 id="一、本季度重点议题" tabindex="-1">一、本季度重点议题 <a class="header-anchor" href="#一、本季度重点议题" aria-label="Permalink to &quot;一、本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区围绕以下几个核心方向持续深入讨论：</p><p><strong>1. RGW 异步化与架构重构</strong><br> RGW 的异步请求重构是本季度最高频的议题，贯穿多次重构会议。核心目标是消除所有阻塞的 librados 调用，并最终大幅缩减线程池规模。详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-28.html">Ceph_RGW_Refactoring_Meeting_2023-06-28</a>) 和 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-07.html">Ceph_RGW_Refactoring_Meeting_2023-06-07</a>)。</p><p><strong>2. BlueStore 性能优化</strong><br> BlueStore 的碎片化处理、弹性共享 Blob（Elastic Shared Blobs）、Codel 算法以及自定义写前锁等多项优化方向在本季度集中讨论，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_BlueStore.html">CDS_Squid_-_BlueStore</a>)。</p><p><strong>3. Squid 版本规划（CDS 峰会）</strong><br> 本季度举办了 Ceph Developer Summit（CDS）Squid 专题，覆盖 BlueStore、Cephadm、Dashboard、RADOS、BD、RGW、NVMe-oF Gateway、Telemetry、Documentation 等几乎所有子系统，为下一个主要版本确立了开发方向。</p><p><strong>4. NVMe-oF Gateway 高可用与可扩展性</strong><br> NVMe-oF Gateway 的 HA 方案、多路径支持、故障转移机制在本季度首次进入系统性讨论阶段，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_NVMe-oF-Gateway.html">CDS_Squid_-_NVMe-oF-Gateway</a>)。</p><p><strong>5. 可观测性与遥测增强</strong><br> 标记性能计数器（labeled perf counters）、Prometheus 集成、Telemetry 数据收集等可观测性方向在多个子系统中同步推进。</p><hr><h2 id="二、技术亮点" tabindex="-1">二、技术亮点 <a class="header-anchor" href="#二、技术亮点" aria-label="Permalink to &quot;二、技术亮点&quot;">​</a></h2><h3 id="bluestore" tabindex="-1">BlueStore <a class="header-anchor" href="#bluestore" aria-label="Permalink to &quot;BlueStore&quot;">​</a></h3><ul><li><strong>弹性共享 Blob（Elastic Shared Blobs）</strong>：已完成开发并回溯到 Quincy 和 Reef 版本，本季度进入测试阶段。该特性优化了克隆对象时的存储效率。</li><li><strong>碎片整理原语</strong>：提出在 BlueStore 中引入对象碎片整理的基本原语，通过空闲周期队列实现碎片整理，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_BlueStore.html">CDS_Squid_-_BlueStore</a>)。</li><li><strong>Codel 算法</strong>：引入 Codel 算法平衡延迟与吞吐量，通过批处理事务提升性能。</li><li><strong>分配器模拟器</strong>：启动 GSoC 合作项目，开发分配器模拟器，用于预测分配器变更对已部署 OSD 的影响。</li></ul><h3 id="rgw" tabindex="-1">RGW <a class="header-anchor" href="#rgw" aria-label="Permalink to &quot;RGW&quot;">​</a></h3><ul><li><strong>异步重构里程碑</strong>：合并了扩展异步处理路径的大型 PR，并计划引入回归测试防止新增阻塞调用，详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-28.html">Ceph_RGW_Refactoring_Meeting_2023-06-28</a>)。</li><li><strong>迁移至 Neo-rados</strong>：发现从 librados 迁移到 Neo-rados 有显著性能提升，开始规划逐步迁移。</li><li><strong>标记性能计数器</strong>：Ali 提交了针对 RGW 前端操作（put/get/delete 等）的标记性能计数器 PR，支持按桶名或用户名过滤，并计划与 Prometheus 集成，详见 <a href="/VideoSummary/posts/2023/RGW_Refactoring_Meeting_2023-08-16.html">RGW_Refactoring_Meeting_2023-08-16</a>)。</li><li><strong>持久化通知改进</strong>：推通知 TTL、重试机制、CLS FIFO 迁移等改进，详见 <a href="/VideoSummary/posts/2023/RGW_Refactoring_Meeting_2023-08-09.html">RGW_Refactoring_Meeting_2023-08-09</a>)。</li><li><strong>OLH 并发 Bug 修复</strong>：Corey Snyder 更新了 OLH 修复 PR，解决并发问题和遗留索引条目问题，详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-14.html">Ceph_RGW_Refactoring_Meeting_2023-06-14</a>)。</li><li><strong>用户存储桶扩展</strong>：讨论通过分片策略突破单个 RADOS 对象 omap 200,000 键上限，详见 <a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-07-05.html">Ceph_RGW_Refactoring_Meeting_2023-07-05</a>)。</li></ul><h3 id="rados" tabindex="-1">RADOS <a class="header-anchor" href="#rados" aria-label="Permalink to &quot;RADOS&quot;">​</a></h3><ul><li><strong>读取均衡器自动化</strong>：讨论将读取均衡器集成到平衡器管理模块，减少人工干预，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_RADOS.html">CDS_Squid_-_RADOS</a>)。</li><li><strong>Erasure Coding简化</strong>：提出为小型集群创建预定义 Erasure 编码配置文件，降低使用门槛。</li><li><strong>MGR Op Tracker</strong>：讨论在 MGR 中实现操作跟踪器，以监控和管理性能问题。</li><li><strong>可用性跟踪</strong>：提出基于 PG 状态的长期可用性跟踪方案。</li></ul><h3 id="rbd" tabindex="-1">RBD <a class="header-anchor" href="#rbd" aria-label="Permalink to &quot;RBD&quot;">​</a></h3><ul><li><strong>镜像数据一致性修复</strong>：确认并规划修复克隆图像同步时的数据损坏问题、丢弃操作未同步问题，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_RBD.html">CDS_Squid_-_RBD</a>)。</li><li><strong>Windows 支持改进</strong>：讨论 Windows NBD 驱动和守护进程的改进，支持持久保留和多路复用。</li><li><strong>实时迁移扩展</strong>：讨论支持从非 Ceph 源进行实时迁移。</li></ul><h3 id="seastore-crimson" tabindex="-1">SeaStore / Crimson <a class="header-anchor" href="#seastore-crimson" aria-label="Permalink to &quot;SeaStore / Crimson&quot;">​</a></h3><ul><li><strong>SeaStore 架构深度解析</strong>：举办代码走读（Code Walkthrough）会议，详细介绍 SeaStore 的 LBA B树、back ref B树、日志记录机制、缓存管理和设备层级管理等核心设计，详见 <a href="/VideoSummary/posts/2023/Ceph_Code_Walkthroughs_-_SeaStore.html">Ceph_Code_Walkthroughs_-_SeaStore</a>)。</li><li>SeaStore 已集成到 Crimson 实验版本，未来六个月优先推进稳定性和性能优化。</li></ul><h3 id="nvme-of-gateway" tabindex="-1">NVMe-oF Gateway <a class="header-anchor" href="#nvme-of-gateway" aria-label="Permalink to &quot;NVMe-oF Gateway&quot;">​</a></h3><ul><li>讨论通过 Gateway Groups 实现 RBD 卷的高可用访问，初步决定由用户通过 CLI 指定首选 Gateway，而非自动负载均衡，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_NVMe-oF-Gateway.html">CDS_Squid_-_NVMe-oF-Gateway</a>)。</li></ul><h3 id="cephadm" tabindex="-1">Cephadm <a class="header-anchor" href="#cephadm" aria-label="Permalink to &quot;Cephadm&quot;">​</a></h3><ul><li>规划 SMB 支持（基于 Samba）、NVMF 支持、升级历史记录功能，以及 FBM 二进制重构，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_Cephadm.html">CDS_Squid_-_Cephadm</a>)。</li></ul><h3 id="测试基础设施" tabindex="-1">测试基础设施 <a class="header-anchor" href="#测试基础设施" aria-label="Permalink to &quot;测试基础设施&quot;">​</a></h3><ul><li><strong>Teuthology 友好化</strong>：GSoC 实习生 Devansh 开发了下一代 Pulpito 仪表板，集成 Teuthology API，支持通过 Web UI 直接调度和终止测试作业，无需 SSH 登录，详见 <a href="/VideoSummary/posts/2023/Ceph_Tech_Talk_-_Making_Teuthology_Friendly.html">Ceph_Tech_Talk_-_Making_Teuthology_Friendly</a>)。</li></ul><hr><h2 id="三、重要决策与里程碑" tabindex="-1">三、重要决策与里程碑 <a class="header-anchor" href="#三、重要决策与里程碑" aria-label="Permalink to &quot;三、重要决策与里程碑&quot;">​</a></h2><p><strong>Reef 版本发布</strong><br> 本季度 Reef 版本正式发布，<a href="/VideoSummary/posts/2023/RGW_Refactoring_Meeting_2023-08-09.html">RGW_Refactoring_Meeting_2023-08-09</a>) 中明确提及发布完成，并计划发布博客文章介绍新功能。</p><p><strong>Squid 版本开发方向确立</strong><br> 通过 CDS Squid 系列专题会议，社区确立了 Squid 版本的核心开发方向，包括：</p><ul><li>BlueStore 碎片整理与分配器模拟器</li><li>Cephadm 的 SMB 和 NVMF 支持</li><li>RGW 异步化完成与线程池缩减</li><li>NVMe-oF Gateway HA 方案落地</li><li>Dashboard 集群升级管理功能</li></ul><p><strong>Cephadm 采用 Python Black 格式化</strong><br><a href="/VideoSummary/posts/2023/Ceph_Orchestrator_Meeting_2023-08-29.html">Ceph_Orchestrator_Meeting_2023-08-29</a>) 决定采用 Python Black 作为 Cephadm 的统一代码格式化工具，并计划纳入 CI 流程。</p><p><strong>RGW resharding 一致性修复回溯</strong><br><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-07.html">Ceph_RGW_Refactoring_Meeting_2023-06-07</a>) 确认将 resharding 一致性 Bug 修复回溯到 Pacific 和 Quincy 版本。</p><p><strong>Elastic Shared Blobs 回溯</strong><br> 弹性共享 Blob 特性已回溯到 Quincy 和 Reef 版本，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_BlueStore.html">CDS_Squid_-_BlueStore</a>)。</p><hr><h2 id="四、社区动态" tabindex="-1">四、社区动态 <a class="header-anchor" href="#四、社区动态" aria-label="Permalink to &quot;四、社区动态&quot;">​</a></h2><p><strong>CDS Squid 峰会</strong><br> 本季度举办了 Ceph Developer Summit Squid 专题，覆盖 BlueStore、Cephadm、Dashboard、Documentation、NVMe-oF Gateway、RADOS、RBD、RGW、Telemetry 等九个子系统的专项规划会议，是本季度社区活动的核心。</p><p><strong>Google Summer of Code（GSoC）</strong></p><ul><li>分配器模拟器项目作为 GSoC 合作项目启动，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_BlueStore.html">CDS_Squid_-_BlueStore</a>)。</li><li>Teuthology 友好化项目由 GSoC 实习生 Devansh 完成，成果在 Tech Talk 中展示，详见 <a href="/VideoSummary/posts/2023/Ceph_Tech_Talk_-_Making_Teuthology_Friendly.html">Ceph_Tech_Talk_-_Making_Teuthology_Friendly</a>)。</li></ul><p><strong>Ceph Quarterly（CQ）新闻简报</strong><br><a href="/VideoSummary/posts/2023/CDS_Squid_-_Documentation.html">CDS_Squid_-_Documentation</a>) 中确认 Ceph Quarterly 新闻简报将每季度发布一次，内容涵盖过去 90 天的开发进展。</p><p><strong>文档清理倡议</strong><br> Zach Dover 主导的 Red House 文档清理倡议接近完成，RADOS 文档清理工作历时约三个月，预计剩余 1000 行即将完成，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_Documentation.html">CDS_Squid_-_Documentation</a>)。</p><p><strong>性能会议持续活跃</strong><br> 本季度性能专项会议持续举行，涵盖 GCC 13 修复、RocksDB 更新策略、Snappy 库替代方案、RBD 性能回归分析、Erasure Coding 缓存优化等议题，详见 <a href="/VideoSummary/posts/2023/Ceph_Performance_Meeting_2023-07-03.html">Ceph_Performance_Meeting_2023-07-03</a>) 和 <a href="/VideoSummary/posts/2023/Ceph_Performance_Meeting_2023-08-17.html">Ceph_Performance_Meeting_2023-08-17</a>)。</p><hr><h2 id="五、下季度展望" tabindex="-1">五、下季度展望 <a class="header-anchor" href="#五、下季度展望" aria-label="Permalink to &quot;五、下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2023Q4 将重点推进以下方向：</p><ol><li><p><strong>RGW 异步化收尾</strong>：完成所有阻塞 librados 调用的消除，推进线程池规模缩减，并开始 Neo-rados 迁移工作。</p></li><li><p><strong>BlueStore 碎片整理落地</strong>：将碎片整理基本原语从设计推进到实现，分配器模拟器进入可用状态。</p></li><li><p><strong>NVMe-oF Gateway HA 方案实现</strong>：完成 Gateway Groups 的多路径配置、故障转移测试，并推进并发 gRPC 处理的设计讨论。</p></li><li><p><strong>Squid 版本功能开发提速</strong>：Cephadm 的 SMB 支持、NVMF 支持、升级历史记录等功能进入开发阶段；Dashboard 集群升级管理功能完成测试。</p></li><li><p><strong>可观测性体系完善</strong>：RGW 标记性能计数器与 Prometheus 完成大规模集成测试；Telemetry 集群内容分析工具开发启动。</p></li><li><p><strong>文档体系建设</strong>：新手入门指南（Beginner&#39;s Guide）和 V-Start 文档规范化在 Squid 发布前完成，详见 <a href="/VideoSummary/posts/2023/CDS_Squid_-_Documentation.html">CDS_Squid_-_Documentation</a>)。</p></li><li><p><strong>SeaStore 稳定性优化</strong>：Crimson 中的 SeaStore 进入稳定性和 RBD 随机读写性能优化阶段，详见 <a href="/VideoSummary/posts/2023/Ceph_Code_Walkthroughs_-_SeaStore.html">Ceph_Code_Walkthroughs_-_SeaStore</a>)。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_BlueStore.html">CDS Squid: BlueStore</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_Cephadm.html">CDS Squid: Cephadm</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_Dashboard.html">CDS Squid: Dashboard</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_Documentation.html">CDS Squid: Documentation</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_NVMe-oF-Gateway.html">CDS Squid: NVMe-oF-Gateway</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_RADOS.html">CDS Squid: RADOS</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_RBD.html">CDS Squid: RBD</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_RGW.html">CDS Squid: RGW</a>)</li><li><a href="/VideoSummary/posts/2023/CDS_Squid_-_Telemetry.html">CDS Squid: Telemetry</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_Code_Walkthroughs_-_SeaStore.html">Ceph Code Walkthroughs: SeaStore</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_Orchestrator_Meeting_2023-08-29.html">Ceph Orchestrator Meeting 2023-08-29</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_Performance_Meeting_2023-07-03.html">Ceph Performance Meeting 2023-07-03</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_Performance_Meeting_2023-08-17.html">Ceph Performance Meeting 2023-08-17</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-07.html">Ceph RGW Refactoring Meeting 2023-06-07</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-14.html">Ceph RGW Refactoring Meeting 2023-06-14</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-28.html">Ceph RGW Refactoring Meeting 2023-06-28</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_RGW_Refactoring_Meeting_2023-07-05.html">Ceph RGW Refactoring Meeting 2023-07-05</a>)</li><li><a href="/VideoSummary/posts/2023/Ceph_Tech_Talk_-_Making_Teuthology_Friendly.html">Ceph Tech Talk: Making Teuthology Friendly</a>)</li><li><a href="/VideoSummary/posts/2023/RGW_Refactoring_Meeting_2023-07-26.html">RGW Refactoring Meeting 2023-07-26</a>)</li><li><a href="/VideoSummary/posts/2023/RGW_Refactoring_Meeting_2023-08-09.html">RGW Refactoring Meeting 2023-08-09</a>)</li><li><a href="/VideoSummary/posts/2023/RGW_Refactoring_Meeting_2023-08-16.html">RGW Refactoring Meeting 2023-08-16</a>)</li></ul>',53)])])}const d=a(i,[["render",l]]);export{S as __pageData,d as default};
